'use strict';
// Interaction-only fixtures. reader.js is copied unchanged from backup c13b594.
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let providers,active,editing=null,current,tab='read';
const request=JSON.stringify({model:'review-model',instructions:'修复函数并运行测试。',input:[{role:'user',content:'修复 add 函数，保持测试不变。'},{type:'function_call',call_id:'call-1',name:'exec_command',arguments:'{"cmd":"pytest -q"}'},{type:'function_call_output',call_id:'call-1',output:'1 passed'}],stream:true},null,2);
const response='event: response.completed\ndata: '+JSON.stringify({type:'response.completed',response:{status:'completed',output:[{type:'message',role:'assistant',content:[{type:'output_text',text:'已修复 add 函数，测试通过。'}]}],usage:{input_tokens:600,output_tokens:220}}})+'\n\n';
const records=[{id:'req-003',turn:'turn-02',session:'session-demo',status:'completed',eof:false,title:'恢复会话 · 确认测试结果',response:response.replace('600','780'),request,time:'10:42:06',tools:0},{id:'req-002',turn:'turn-01',session:'session-demo',status:'completed',eof:true,title:'工具结果返回 · 完成修复',response:response.replace('"output":[','"output":[{"type":"function_call","name":"exec_command","call_id":"call-2","arguments":"pytest -q"},'),request,time:'10:40:12',tools:1},{id:'req-001',turn:'',session:'',status:'incomplete',eof:false,title:'未关联请求 · 客户端断开',response:'event: response.output_text.delta\ndata: {"type":"response.output_text.delta","delta":"正在检查"}\n\n',request,time:'10:39:58',tools:0}];
function notice(s){$('#notice').textContent=s;}
function reset(){providers=[{id:'primary',name:'Codex 主连接',url:'https://gateway.example.test/v1',model:'review-model',env:'CODEX_UPSTREAM_KEY',mode:'preserve',protocol:'responses',tested:true,configured:true},{id:'standby',name:'备用 Responses',url:'https://standby.example.test/v1',model:'review-model',env:'STANDBY_KEY',mode:'override',protocol:'responses',tested:false,configured:true},{id:'deepseek',name:'DeepSeek 预设',url:'https://api.deepseek.com/v1',model:'deepseek-chat',env:'DEEPSEEK_API_KEY',mode:'preserve',protocol:'chat_completions',tested:false,configured:false}];active='primary';render();notice('模拟操作 · 刷新即重置 · 不调用模型');}
function render(){const a=providers.find(p=>p.id===active);$('#active-name').textContent=a.name;$('#provider-list').innerHTML=providers.map(p=>`<article data-provider="${esc(p.id)}" class="${active===p.id?'active':''}"><div class="title"><h2>${esc(p.name)}</h2><span class="pill ${p.protocol!=='responses'?'warn':''}">${active===p.id?'使用中':p.protocol==='responses'?'可接入 Codex':'后续闭环'}</span></div><small>${esc(p.id)} · ${esc(p.protocol)}</small><div class="endpoint">${esc(p.url)}</div><dl><dt>默认模型</dt><dd>${esc(p.model)}</dd><dt>模型策略</dt><dd>${p.mode==='preserve'?'保留请求模型':'覆盖请求模型'}</dd><dt>凭据</dt><dd>${p.configured?'已加载':'未加载'} · ${esc(p.env)}</dd><dt>测试</dt><dd>${p.tested?'通过 · 当前配置 · 24h 内':'未通过 / 待测试'}</dd></dl><div class="actions"><button data-action="edit" data-id="${esc(p.id)}">${active===p.id?'另存':'编辑'}</button><button data-action="test" data-id="${esc(p.id)}" ${p.protocol!=='responses'?'disabled':''}>测试连接</button><button data-action="activate" data-id="${esc(p.id)}" ${active===p.id||!p.tested||!p.configured||p.protocol!=='responses'?'disabled':''}>切换使用</button></div></article>`).join('');renderRecords();renderSessions();}
function page(id){document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==id);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('selected',e.dataset.page===id));}
function editor(id){const p=providers.find(p=>p.id===id),copy=id===active;editing=p&&!copy?id:null;const f=$('#form');f.reset();for(const key of ['id','name','url','protocol','model','env','mode'])f.elements[key].value=p?p[key]:({protocol:'responses',mode:'preserve'}[key]||'');if(copy){let n=id+'-copy';while(providers.some(p=>p.id===n))n+='-copy';f.elements.id.value=n;f.elements.name.value=p.name+' 副本';}f.elements.id.readOnly=!!editing;$('#edit-title').textContent=copy?'另存活动连接':p?'编辑连接':'新增连接';$('#form-error').textContent='';$('#editor').showModal();}
$('#form').onsubmit=e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));try{const u=new URL(p.url);if(!((u.protocol==='https:')||(u.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(u.hostname)))||u.username||u.password||u.search||u.hash)throw Error('使用 HTTPS 或本机 HTTP；地址不包含凭据、查询或片段。');if(!editing&&providers.some(x=>x.id===p.id))throw Error('连接 ID 已存在。');const old=providers.find(x=>x.id===editing);p.configured=old?.configured??false;p.tested=false;if(old)providers[providers.indexOf(old)]=p;else providers.push(p);$('#editor').close();render();notice('已保存 · 需要重新测试；活动连接未变化');}catch(err){$('#form-error').textContent=err.message;}};
$('#provider-list').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const p=providers.find(p=>p.id===b.dataset.id);if(b.dataset.action==='edit')return editor(p.id);if(b.dataset.action==='test'){const result=$('#scenario').value;p.tested=result==='success';p.configured=result!=='missing';render();notice(result==='success'?'测试通过 · 可切换使用':result==='missing'?'测试失败 · 未加载凭据':'测试失败 · 上游错误');}if(b.dataset.action==='activate'&&p.tested&&p.configured&&p.protocol==='responses'){active=p.id;render();notice('已切换 · 新请求使用此连接，在途请求保留原快照');}};
function row(r){return `<button class="row" data-request="${r.id}"><span>${esc(r.title)}<small>${r.id} · ${r.time} · ${r.tools} 工具调用</small></span><span class="pill ${r.status==='completed'?'':'warn'}">${r.status==='completed'?'协议完成':'协议未完成'} / ${r.eof?'正文收全':'正文部分'}</span></button>`;}
function renderRecords(){const f=$('#filter').value;const rows=records.filter(r=>f==='all'||f===r.status||(f==='unlinked'&&!r.session));$('#request-list').innerHTML=rows.map(row).join('')||'<div class="empty">没有匹配请求</div>';}
function renderSessions(){const q=$('#search').value.trim().toLowerCase();$('#session-list').innerHTML=!q||('session-demo 修复 add 函数').includes(q)?'<button id="open-session" class="row"><span>修复 add 函数<small>session-demo · 2 turns · 2 请求 · 1 工具调用</small></span><span>展开时间线 →</span></button>':'<div class="empty">没有匹配会话</div>';$('#timeline').innerHTML='';}
function detail(id){current=records.find(r=>r.id===id);tab='read';$('#format').checked=false;$('#user-only').checked=false;$('#detail').showModal();renderDetail();}
function cards(result){return result.cards.map(c=>`<article class="read-card ${esc(c.role)}"><b>${esc(c.label)}${c.name?' · '+esc(c.name):''}</b><pre>${esc(c.text)}</pre></article>`).join('')+(result.notes||[]).map(n=>`<p class="muted">${esc(n)}</p>`).join('');}
function renderDetail(){const r=current;$('#detail-title').textContent=r.id;$('#detail-badges').innerHTML=`<span class="pill">${r.status}</span> <span class="pill ${r.eof?'':'warn'}">HTTP EOF ${r.eof?'已到达':'未到达 · 正文可能不完整'}</span>`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));$('#raw-actions').hidden=!['request','response'].includes(tab);$('#user-only-label').hidden=tab!=='request';let content;if(tab==='read')content='<h3>发送内容</h3>'+cards(TraceReader.request(r.request))+'<h3>上游返回</h3>'+cards(TraceReader.response(r.response));else if(tab==='overview')content=`<dl><dt>Provider</dt><dd>Codex 主连接 · 请求时快照</dd><dt>Session</dt><dd>${r.session||'未关联'}</dd><dt>Turn</dt><dd>${r.turn||'未知'}</dd><dt>工具调用</dt><dd>${r.tools}</dd><dt>协议</dt><dd>${r.status}</dd><dt>HTTP EOF</dt><dd>${r.eof}</dd></dl>`;else{let raw=r[tab];if(tab==='request'&&$('#user-only').checked)raw=TraceReader.userText(raw);else if($('#format').checked){try{raw=JSON.stringify(JSON.parse(raw),null,2);}catch{raw=raw.split('\n').map(l=>{if(!l.startsWith('data: '))return l;try{return 'data: '+JSON.stringify(JSON.parse(l.slice(6)),null,2);}catch{return l;}}).join('\n');}}content='<pre>'+esc(raw)+'</pre>';}$('#detail-content').innerHTML=content;}
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(current[tab]);$('#copy').textContent='已复制原文';}catch{$('#copy').textContent='复制不可用 · 请下载';}};
$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([current[tab]],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=current.id+'-'+tab+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#refresh').onclick=()=>{$('#refresh').textContent='已刷新 · 示例无新增字节';renderDetail();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)page(b.dataset.page);if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.request)detail(b.dataset.request);if(b.dataset.tab){tab=b.dataset.tab;$('#copy').textContent='复制原文';renderDetail();}if(b.id==='open-session')$('#timeline').innerHTML=[...records].reverse().filter(r=>r.session).map(r=>'<h3 class="turn">thread-demo / '+r.turn+'</h3>'+row(r)).join('');});
$('#add').onclick=()=>editor();$('#expire').onclick=()=>{providers.forEach(p=>p.tested=false);render();notice('测试已过期 · 当前活动连接继续使用，切换需重新测试');};$('#reset').onclick=reset;$('#search').oninput=renderSessions;$('#filter').onchange=renderRecords;$('#format').onchange=renderDetail;$('#user-only').onchange=renderDetail;reset();page('providers');
